export default async (req, res) => {
  await connectToMongoDB();

  if (req.method === 'GET') {
    const data = await getData(req);
    res.status(200).json(data);
  } else if (req.method === 'POST') {
    const data = await createData(req);
    res.status(201).json(data);
  } else if (req.method === 'PUT') {
    const data = await updateData(req);
    res.status(200).json(data);
  } else if (req.method === 'DELETE') {
    const data = await deleteData(req);
    res.status(200).json(data);
  } else {
    res.status(405).json({ error: 'Method not allowed' });
  }
};

async function getData(req) {
  const { collection } = req.query;
  const client = await connectToMongoDB();
  const db = client.db('your_database_name');
  const data = await db.collection(collection).find().toArray();
  return data;
}

async function createData(req) {
  const { collection, data } = req.body;
  const client = await connectToMongoDB();
  const db = client.db('your_database_name');
  const result = await db.collection(collection).insertOne(data);
  return result;
}

async function updateData(req) {
  const { collection, data, id } = req.body;
  const client = await connectToMongoDB();
  const db = client.db('your_database_name');
  const result = await db.collection(collection).updateOne({ _id: ObjectId(id) }, { $set: data });
  return result;
}

async function deleteData(req) {
  const { collection, id } = req.body;
  const client = await connectToMongoDB();
  const db = client.db('your_database_name');
  const result = await db.collection(collection).deleteOne({ _id: ObjectId(id) });
  return result;
}
