                for (Cell cell : row) {
                    rowData.add(cell.getStringCellValue());
                }

                data.add(rowData);
            }

            for (List<String> rowData : data) {
                String csvRow = String.join(",", rowData);
                outputStream.appendText(csvRow).appendLine();
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
