Query: I want to parse a struct in a go source file and want to generate a avro schema from it. Please write a Go program that receives the name of the Go source file and the name of the struct that should be converted. It should output a file named struct.avsc

Response A: 

Here's a Go program that does what you described:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"strings"

	"github.com/apache/avro/v2/avro"
	"github.com/apache/avro/v2/schema"
)

func main() {
	goFile := "example.go"
	structName := "MyStruct"

	content, err := ioutil.ReadFile(goFile)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Extract the struct definition from the Go file
	structDef := extractStructDef(content, structName)
	if structDef == nil {
		fmt.Println("Unable to extract struct definition")
		return
	}

	// Generate the AVRO schema
	schemaDef, err := generateSchema(structDef)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Write the schema to a file
	err = ioutil.WriteFile("struct.avsc", schemaDef, 0644)
	if err != nil {
		fmt.Println(err)
		return
	}
}

func extractStructDef(content []byte, structName string) *schema.Struct {
	// Parse the Go code to extract the struct definition
	// This implementation uses a simple regex to match the struct definition
	// You may need to modify it to handle more complex Go code
	regex := `struct\s+` + structName + `\s+` + `{` + `\s*(.+?)\s*` + `\}`
	match := regexp.MustCompile(regex).FindStringSubmatch(string(content))
	if len(match) != 2 {
		return nil
	}

	fields := []schema.Field{}
	for _, field := range strings.Split(match[1], ",") {
		field = strings.TrimSpace(field)
		parts := strings.Split(field, " ")
		if len(parts) != 2 {
			continue
		}
		name := parts[0]
		typeName := parts[1]
		fields = append(fields, schema.Field{Name: name, Type: typeName})
	}

	return &schema.Struct{Name: structName, Fields: fields}
}

func generateSchema(structDef *schema.Struct) ([]byte, error) {
	// Generate the AVRO schema using the extracted struct definition
	// This implementation uses the avro/v2/schema package to generate the schema
	schemaDef, err := avro.NewSchema(structDef)
	if err != nil {
		return nil, err
	}

	return schemaDef.ToJSON(), nil
}
```

