    if ($user) {
        return $user.SIDHistory
    }

    $group = (Get-ADGroup -Filter "SID -eq '$sid'" -Properties SID, SIDHistory).SID
    if ($group) {
        return $group.SIDHistory
    }

    return $null
}

# Define the function to recursively check the folders
function CheckFolders {
