        $acl = (Get-Acl -Path $_.FullName).Access
        $sidHistory = CheckSIDHistory($acl.IdentityReference)

        if ($sidHistory) {
            Write-Host "SID History found in ACL of $($_.Name): $sidHistory"
        }

        CheckFolders($_.FullName)
